begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();
create temporary table subjects(n integer primary key, id uuid, email text);
insert into subjects select n, ('00000000-0000-4000-8000-' || lpad(n::text,12,'0'))::uuid, 'user' || n || '@example.test' from generate_series(1,6) n;
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data)
  select id,email,case when n=6 then null else now() end,'{"provider":"google","providers":["google"]}' from subjects where n<>5;
insert into auth.identities(id,provider_id,user_id,provider,identity_data)
  select gen_random_uuid(),id::text,id,'google',jsonb_build_object('sub',id::text,'email',email,'email_verified',n<>6) from subjects where n<>5;
insert into auth.sessions(id,user_id,created_at,updated_at) select id,id,now(),now() from subjects where n<>5;
create temporary table ids(name text primary key,id uuid);
grant all on subjects, ids to authenticated;
create function pg_temp.actor(n integer, method text default 'oauth') returns void language plpgsql as $$
begin perform set_config('request.jwt.claims',jsonb_build_object('sub',s.id,'role','authenticated','session_id',s.id,'amr',jsonb_build_array(jsonb_build_object('method',method)))::text,true) from subjects s where s.n=actor.n; end;
$$;
-- Test-only shared rows exercise the membership predicate for future clinical tables.
-- No clinical data endpoint is shipped before quotas.
create table public.rls_probe(id uuid primary key default gen_random_uuid(),clinic_id uuid not null references public.clinics(id) on delete cascade, value text);
alter table public.rls_probe enable row level security;
grant select,insert,update,delete on public.rls_probe to authenticated;
create policy probe_access on public.rls_probe for all to authenticated using(clinic_private.is_member(clinic_id)) with check(clinic_private.is_member(clinic_id));
set local role authenticated;
select pg_temp.actor(1);
insert into ids values('a',public.manage_clinic('create',null,'Alameda',array[' USER3@example.test ','user5@example.test']));
select is((select count(*)::integer from public.clinic_access),3,'creator and two emails added atomically');
select is((select count(*)::integer from public.clinic_access where user_id is null),1,'unknown account remains pending');
select is((select owner_id from public.clinics),(select id from subjects where n=1),'owner comes from authenticated actor');
select throws_ok($$select public.manage_clinic('create',null,'Invalid',array['invalid'])$$,'22023','Invalid email','invalid email rolls back creation');
select is((select count(*)::integer from public.clinics),1,'failed create left no clinic');
select lives_ok($$select public.manage_clinic('add',(select id from ids where name='a'),null,array['USER3@example.test'])$$,'duplicate membership is idempotent');
select is((select count(*)::integer from public.clinic_access),3,'duplicate did not add a row');
select throws_ok($$select public.manage_clinic('remove',(select id from ids where name='a'),null,'{}',(select id from public.clinic_access where user_id=auth.uid()))$$,'22023','Cannot remove member','owner cannot remove self');
select pg_temp.actor(2);
insert into ids values('b',public.manage_clinic('create',null,'Bosque'));
select is((select count(*)::integer from public.clinics),1,'second owner cannot read first clinic');
select pg_temp.actor(3);
select is((select count(*)::integer from public.clinics),1,'member sees own clinic only');
select is((select count(*)::integer from public.clinic_access),3,'member cannot enumerate another team');
select throws_ok($$select public.manage_clinic('rename',(select id from ids where name='a'),'Stolen')$$,'42501','Not authorized','member cannot rename');
select throws_ok($$select public.manage_clinic('delete',(select id from ids where name='a'))$$,'42501','Not authorized','member cannot delete clinic');
select throws_ok($$select public.manage_clinic('add',(select id from ids where name='a'),null,array['user4@example.test'])$$,'42501','Not authorized','member cannot invite');
select throws_ok($$update public.clinics set owner_id=auth.uid()$$,'42501','permission denied for table clinics','direct ownership escalation denied');
select throws_ok($$insert into public.clinic_access(clinic_id,user_id,email) values((select id from ids where name='b'),auth.uid(),'user3@example.test')$$,'42501','permission denied for table clinic_access','direct self enrollment denied');
select throws_ok($$delete from public.clinic_access$$,'42501','permission denied for table clinic_access','direct membership deletion denied');
select lives_ok($$insert into public.rls_probe(clinic_id,value) values((select id from ids where name='a'),'synthetic')$$,'member can insert shared data');
select lives_ok($$update public.rls_probe set value='updated'$$,'member can update shared data');
select is((select value from public.rls_probe),'updated','member can read shared data');
select throws_ok($$update public.rls_probe set clinic_id=(select id from ids where name='b')$$,'42501','new row violates row-level security policy for table "rls_probe"','cannot move row to foreign clinic');
select throws_ok($$insert into public.rls_probe(clinic_id,value) values((select id from ids where name='b'),'foreign')$$,'42501','new row violates row-level security policy for table "rls_probe"','cannot insert foreign row');
select pg_temp.actor(4);
select is((select count(*)::integer from public.clinics),0,'outsider sees no clinics');
select is((select count(*)::integer from public.rls_probe),0,'outsider sees no shared rows');
select results_eq($$with d as (delete from public.rls_probe returning id) select count(*)::integer from d$$,array[0],'outsider cannot delete shared rows');
select results_eq($$with u as (update public.rls_probe set value='attack' returning id) select count(*)::integer from u$$,array[0],'outsider cannot update shared rows');
select throws_ok($$select public.manage_clinic('delete',(select id from ids where name='a'))$$,'42501','Not authorized','outsider cannot delete clinic via RPC');
select throws_ok($$select clinic_private.manage_clinic('rename',(select id from ids where name='a'),'attack')$$,'42501','Not authorized','private implementation also checks authority');
select is(public.claim_clinic_invitations(),0,'outsider cannot claim another email invitation');
select set_config('request.jwt.claims', (current_setting('request.jwt.claims')::jsonb || '{"email":"user5@example.test","user_metadata":{"email_verified":true,"role":"owner"}}'::jsonb)::text,true);
select is(public.claim_clinic_invitations(),0,'forged email and user metadata do not authorize invitations');
select throws_ok($$select public.manage_clinic('rename',(select id from ids where name='a'),'metadata attack')$$,'42501','Not authorized','user metadata cannot grant owner role');
select pg_temp.actor(6);
select throws_ok($$select public.manage_clinic('create',null,'unverified')$$,'42501','Google verified identity required','unverified Google email denied');
select pg_temp.actor(1,'password');
select throws_ok($$select public.manage_clinic('create',null,'password')$$,'42501','Google verified identity required','non OAuth session denied even with linked Google');
reset role;
insert into auth.users(id,email,email_confirmed_at) select id,email,now() from subjects where n=5;
insert into auth.identities(id,provider_id,user_id,provider,identity_data) select gen_random_uuid(),id::text,id,'google',jsonb_build_object('email',email,'email_verified',true) from subjects where n=5;
insert into auth.sessions(id,user_id,created_at,updated_at) select id,id,now(),now() from subjects where n=5;
set local role authenticated;
select pg_temp.actor(5);
select is(public.claim_clinic_invitations(),1,'new verified user claims reserved invitation');
select is(public.claim_clinic_invitations(),0,'claim is idempotent');
select is((select count(*)::integer from public.clinics),1,'new member can see clinic');
select pg_temp.actor(1);
insert into ids values('member3',(select id from public.clinic_access where user_id=(select id from subjects where n=3)));
select lives_ok($$select public.manage_clinic('remove',(select id from ids where name='a'),null,'{}',(select id from ids where name='member3'))$$,'owner removes member');
select pg_temp.actor(3);
select is((select count(*)::integer from public.clinics),0,'removed user loses read access with same session');
select throws_ok($$insert into public.rls_probe(clinic_id,value) values((select id from ids where name='a'),'revoked')$$,'42501','new row violates row-level security policy for table "rls_probe"','removed user loses write access');
select is(public.claim_clinic_invitations(),0,'removed member cannot rejoin by claiming');
select pg_temp.actor(5);
select lives_ok($$delete from public.rls_probe$$,'active member can delete shared data');
select is((select count(*)::integer from public.rls_probe),0,'shared deletion actually happened');
select pg_temp.actor(1);
insert into public.rls_probe(clinic_id,value) values((select id from ids where name='a'),'cascade');
select lives_ok($$select public.manage_clinic('rename',(select id from ids where name='a'),'Alameda nueva')$$,'owner can rename');
select lives_ok($$select public.manage_clinic('delete',(select id from ids where name='a'))$$,'owner can delete clinic');
reset role;
select is((select count(*)::integer from public.clinic_access where clinic_id=(select id from ids where name='a')),0,'delete cascades memberships');
select is((select count(*)::integer from public.rls_probe),0,'delete cascades shared rows');
select is((select count(*)::integer from public.clinics where id=(select id from ids where name='b')),1,'other fixture clinic remains intact alongside existing local data');
delete from auth.sessions where user_id=(select id from subjects where n=2);
set local role authenticated;
select pg_temp.actor(2);
select is((select count(*)::integer from public.clinics),0,'revoked session loses access despite unexpired JWT');
select throws_ok($$select public.manage_clinic('create',null,'expired session')$$,'42501','Google verified identity required','revoked session cannot mutate');
reset role;
set local role anon;
select throws_ok($$select * from public.clinics$$,'42501','permission denied for table clinics','anonymous cannot read clinics');
select throws_ok($$select public.manage_clinic('create',null,'anonymous')$$,'42501','permission denied for function manage_clinic','anonymous cannot call write RPC');
select throws_ok($$select public.claim_clinic_invitations()$$,'42501','permission denied for function claim_clinic_invitations','anonymous cannot claim invitations');
select throws_ok($$insert into public.clinics(name,owner_id) values('anon','00000000-0000-4000-8000-000000000001')$$,'42501','permission denied for table clinics','anonymous cannot insert');
select throws_ok($$update public.clinics set name='anon'$$,'42501','permission denied for table clinics','anonymous cannot update');
select throws_ok($$delete from public.clinics$$,'42501','permission denied for table clinics','anonymous cannot delete');
reset role;
select is((select count(*)::integer from pg_publication_tables where schemaname='public' and tablename in ('clinics','clinic_access')),0,'no Realtime publication');
select is((select count(*)::integer from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('manage_clinic','claim_clinic_invitations') and p.prosecdef),0,'public RPCs are security invoker');
select * from finish();
rollback;
